/// Equivalent to `UAX29URLEmailTokenizerImpl.zzUnpackTrans()`.
fn zz_unpack_trans() -> Box<[i32]> {
    let mut result = vec![0; 1095920];
    let mut offset = 0;
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_0), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_1), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_2), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_3), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_4), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_5), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_6), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_7), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_8), offset, &mut result);
    offset = zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_9), offset, &mut result);
    zz_unpack_trans_packed(&utf16(ZZ_TRANS_PACKED_10), offset, &mut result);
    result.into_boxed_slice()
}

/// Equivalent to `UAX29URLEmailTokenizerImpl.zzUnpackTrans(String, int, int[])`.
fn zz_unpack_trans_packed(packed: &[u16], offset: usize, result: &mut [i32]) -> usize {
    let mut i = 0; /* index in packed string  */
    let mut j = offset; /* index in unpacked array */
    let l = packed.len();
    while i < l {
        let mut count = i32::from(packed[i]);
        i += 1;
        let mut value = i32::from(packed[i]);
        i += 1;
        value -= 1;
        loop {
            result[j] = value;
            j += 1;
            count -= 1;
            if count <= 0 {
                break;
            }
        }
    }
    j
}

